/// Returns proc address from get_proc_address lookup table function.
fn pa(
    get_proc_address: GDExtensionInterfaceGetProcAddress,
    comptime name: [:0]const u8,
    comptime T: type,
) !T {
    return @ptrCast(@alignCast(get_proc_address(name.ptr)));
}

